#include "kernel.h"
#include <hls_math.h>
#include <stdint.h>

// ---------------------------------------------------------------------------
// Internal double-precision helpers (HLS synthesises these as DSP chains)
// ---------------------------------------------------------------------------

static double d_sqrt(double x) { return hls::sqrt(x); }
static double d_atan(double x) { return hls::atan(x); }
static double d_cos(double x)  { return hls::cos(x);  }
static double d_sin(double x)  { return hls::sin(x);  }
static double d_atan2(double y, double x) { return hls::atan2(y, x); }

// ---------------------------------------------------------------------------
// kernel_top
// ---------------------------------------------------------------------------
void kernel_top(
    acm_t  A_re[N][N],
    acm_t  A_im[N][N],
    iter_t max_iter,
    eval_t eigenvalues_re[N],
    eval_t eigenvalues_im[N],
    evec_t eigenvectors_re[N][N],
    evec_t eigenvectors_im[N][N],
    iter_t &ite,
    uint32_t &clock_cycles)
{
#pragma HLS INTERFACE ap_ctrl_hs port=return
#pragma HLS INLINE off

    // ------------------------------------------------------------------
    // Working arrays in double precision
    // ------------------------------------------------------------------
    double AR[N][N], AI[N][N];   // matrix A (real/imag)
    double VR[N][N], VI[N][N];   // eigenvector accumulator V

    // Initialise A from inputs, V = identity
    INIT_ROW: for (int i = 0; i < N; i++) {
        INIT_COL: for (int j = 0; j < N; j++) {
            AR[i][j] = (double)A_re[i][j];
            AI[i][j] = (double)A_im[i][j];
            VR[i][j] = (i == j) ? 1.0 : 0.0;
            VI[i][j] = 0.0;
        }
    }

    clock_cycles = 0;
    uint32_t local_cycles = 0;

    int last_z = 0;

    // ------------------------------------------------------------------
    // Main Jacobi loop
    // ------------------------------------------------------------------
    JACOBI_OUTER: for (int z = 0; z < (int)max_iter; z++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=1000 avg=100

        // ---- find largest off-diagonal element -------------------------
        double off_diag_max = 0.0;
        int p = 0, q = 1;

        FIND_P: for (int i = 0; i < N; i++) {
            FIND_Q: for (int j = i + 1; j < N; j++) {
                double re = AR[i][j], im = AI[i][j];
                double mag = d_sqrt(re*re + im*im);
                local_cycles++;
                if (mag > off_diag_max) {
                    off_diag_max = mag;
                    p = i;
                    q = j;
                }
            }
        }
        local_cycles++; // outer iteration overhead

        // ---- convergence check -----------------------------------------
        if (off_diag_max < 1e-8) {
            last_z = z;
            break;
        }
        last_z = z;

        // ---- compute rotation angles -----------------------------------
        double app_r = AR[p][p], app_i = AI[p][p];
        double aqq_r = AR[q][q], aqq_i = AI[q][q];
        double apq_r = AR[p][q], apq_i = AI[p][q];

        double apq_abs = d_sqrt(apq_r*apq_r + apq_i*apq_i);
        double denom   = (app_r - aqq_r);   // real part of (a_pp - a_qq)

        double theta;
        if (denom == 0.0 && apq_abs == 0.0) {
            theta = 0.0;
        } else {
            theta = 0.5 * d_atan((2.0 * apq_abs) / denom);
        }

        double phi = -d_atan2(apq_i, apq_r); // -angle(a_pq)

        double cos_t = d_cos(theta);
        double sin_t = d_sin(theta);
        double cos_p = d_cos(phi);
        double sin_p = d_sin(phi);

        // U[p,p] =  cos(theta)
        // U[p,q] =  sin(theta)*exp(-i*phi) =  sin_t*(cos_p - i*sin_p)
        // U[q,p] =  sin(theta)*exp( i*phi) =  sin_t*(cos_p + i*sin_p)
        // U[q,q] = -cos(theta)
        double Upp_r =  cos_t,  Upp_i = 0.0;
        double Upq_r =  sin_t * cos_p,  Upq_i = -sin_t * sin_p;
        double Uqp_r =  sin_t * cos_p,  Uqp_i =  sin_t * sin_p;
        double Uqq_r = -cos_t, Uqq_i = 0.0;

        // ---- A <- U^H * A * U ------------------------------------------
        // Temporary storage
        double TR[N][N], TI[N][N]; // intermediate = U^H * A

        // U^H has nonzero (non-identity) entries only in rows p and q
        // For rows other than p,q: (U^H)[k,k] = 1  (identity row)
        // (U^H)[p,p] = conj(Upp) = cos_t,      (U^H)[p,q] = conj(Uqp)
        // (U^H)[q,p] = conj(Upq),               (U^H)[q,q] = conj(Uqq) = -cos_t

        double cUpp_r =  cos_t,  cUpp_i =  0.0;
        double cUpq_r =  Uqp_r,  cUpq_i = -Uqp_i;  // conj(Uqp)
        double cUqp_r =  Upq_r,  cUqp_i = -Upq_i;  // conj(Upq)
        double cUqq_r = -cos_t,  cUqq_i =  0.0;

        // TR = U^H * A  (only rows p and q change)
        UH_A_ROW: for (int k = 0; k < N; k++) {
            for (int j = 0; j < N; j++) {
                TR[k][j] = AR[k][j];
                TI[k][j] = AI[k][j];
            }
        }
        // row p of TR
        for (int j = 0; j < N; j++) {
            double ar = AR[p][j], ai = AI[p][j];
            double br = AR[q][j], bi = AI[q][j];
            TR[p][j] = cUpp_r*ar - cUpp_i*ai + cUpq_r*br - cUpq_i*bi;
            TI[p][j] = cUpp_r*ai + cUpp_i*ar + cUpq_r*bi + cUpq_i*br;
            local_cycles++;
        }
        // row q of TR
        for (int j = 0; j < N; j++) {
            double ar = AR[p][j], ai = AI[p][j];
            double br = AR[q][j], bi = AI[q][j];
            TR[q][j] = cUqp_r*ar - cUqp_i*ai + cUqq_r*br - cUqq_i*bi;
            TI[q][j] = cUqp_r*ai + cUqp_i*ar + cUqq_r*bi + cUqq_i*br;
            local_cycles++;
        }

        // A = TR * U  (only columns p and q change)
        double AR2[N][N], AI2[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                AR2[i][j] = TR[i][j];
                AI2[i][j] = TI[i][j];
            }
        }
        // col p of A2
        for (int i = 0; i < N; i++) {
            double ar = TR[i][p], ai = TI[i][p];
            double br = TR[i][q], bi = TI[i][q];
            AR2[i][p] = ar*Upp_r - ai*Upp_i + br*Uqp_r - bi*Uqp_i;
            AI2[i][p] = ar*Upp_i + ai*Upp_r + br*Uqp_i + bi*Uqp_r;
            local_cycles++;
        }
        // col q of A2
        for (int i = 0; i < N; i++) {
            double ar = TR[i][p], ai = TI[i][p];
            double br = TR[i][q], bi = TI[i][q];
            AR2[i][q] = ar*Upq_r - ai*Upq_i + br*Uqq_r - bi*Uqq_i;
            AI2[i][q] = ar*Upq_i + ai*Upq_r + br*Uqq_i + bi*Uqq_r;
            local_cycles++;
        }

        // Enforce exact zero at (p,q) and (q,p)
        AR2[p][q] = 0.0; AI2[p][q] = 0.0;
        AR2[q][p] = 0.0; AI2[q][p] = 0.0;

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                AR[i][j] = AR2[i][j];
                AI[i][j] = AI2[i][j];
            }
        }

        // ---- V <- V * U ------------------------------------------------
        double VR2[N][N], VI2[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                VR2[i][j] = VR[i][j];
                VI2[i][j] = VI[i][j];
            }
        }
        // only cols p and q change
        V_COL_P: for (int i = 0; i < N; i++) {
            double vr = VR[i][p], vi = VI[i][p];
            double wr = VR[i][q], wi = VI[i][q];
            VR2[i][p] = vr*Upp_r - vi*Upp_i + wr*Uqp_r - wi*Uqp_i;
            VI2[i][p] = vr*Upp_i + vi*Upp_r + wr*Uqp_i + wi*Uqp_r;
            local_cycles++;
        }
        V_COL_Q: for (int i = 0; i < N; i++) {
            double vr = VR[i][p], vi = VI[i][p];
            double wr = VR[i][q], wi = VI[i][q];
            VR2[i][q] = vr*Upq_r - vi*Upq_i + wr*Uqq_r - wi*Uqq_i;
            VI2[i][q] = vr*Upq_i + vi*Upq_r + wr*Uqq_i + wi*Uqq_r;
            local_cycles++;
        }
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                VR[i][j] = VR2[i][j];
                VI[i][j] = VI2[i][j];
            }
        }
    } // end JACOBI_OUTER

    clock_cycles = local_cycles;

    // ------------------------------------------------------------------
    // Pack outputs
    // ------------------------------------------------------------------
    OUT_EVAL: for (int i = 0; i < N; i++) {
        eigenvalues_re[i] = (eval_t)AR[i][i];
        eigenvalues_im[i] = (eval_t)AI[i][i];
    }
    OUT_EVEC: for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            eigenvectors_re[i][j] = (evec_t)VR[i][j];
            eigenvectors_im[i][j] = (evec_t)VI[i][j];
        }
    }
    ite = (iter_t)last_z;
}

