        double apq_abs = d_sqrt(apq_r*apq_r + apq_i*apq_i);
        double denom   = app_r - aqq_r;

        // 2*theta = atan2(2*|apq|, denom)  in range (-pi, pi)
        // theta in (-pi/2, pi/2), but we want theta in (-pi/4, pi/4)
        // so we use: theta = 0.5 * atan2(2*|apq|, denom)
        // Since 2*|apq| >= 0, the atan2 result is in [0, pi], so theta in [0, pi/2]
        // but we may want to choose the smaller rotation for stability:
        // if theta > pi/4, use theta - pi/2 (equivalent rotation)
        double two_theta = d_atan2(2.0 * apq_abs, denom);
        double theta = 0.5 * two_theta;
        // Ensure theta in (-pi/4, pi/4]: if theta > pi/4, subtract pi/2
        // (atan2 with positive first arg gives result in [0,pi], so theta in [0,pi/2])
        // We want the minimal rotation:
        if (theta > 0.7853981633974483) {  // pi/4
            theta -= 1.5707963267948966;    // pi/2
        }

        double phi = -d_atan2(apq_i, apq_r); // -arg(A[p][q])

        double cos_t = d_cos(theta);
        double sin_t = d_sin(theta);
        double cos_p = d_cos(phi);
        double sin_p = d_sin(phi);

        // U matrix elements:
        // U[p][p] = cos_t
        // U[q][q] = cos_t
        // U[p][q] = sin_t * exp(i*phi) = sin_t*(cos_p + i*sin_p)
        // U[q][p] = -sin_t * exp(-i*phi) = -sin_t*(cos_p - i*sin_p)
        double Upp_r =  cos_t,  Upp_i = 0.0;
        double Uqq_r =  cos_t,  Uqq_i = 0.0;
        double Upq_r =  sin_t * cos_p,  Upq_i =  sin_t * sin_p;
        double Uqp_r = -sin_t * cos_p,  Uqp_i =  sin_t * sin_p;

        // U^H elements (conjugate transpose of U):
        // U^H[p][p] = cos_t
        // U^H[q][q] = cos_t
        // U^H[p][q] = conj(U[q][p]) = -sin_t*(cos_p + i*sin_p) -> wait:
        //   U^H[i][j] = conj(U[j][i])
        // U^H[p][p] = conj(U[p][p]) = cos_t
        // U^H[p][q] = conj(U[q][p]) = conj(-sin_t*(cos_p - i*sin_p)) = -sin_t*(cos_p + i*sin_p)
        //           = -Upq_r - i*Upq_i ... hmm let me redo
        //
        // Actually: U[q][p] = -sin_t*(cos_p - i*sin_p)
        //   So conj(U[q][p]) = -sin_t*(cos_p + i*sin_p)
        // U^H[p][q] = conj(U[q][p]) = -sin_t*cos_p - i*sin_t*sin_p
        // U^H[q][p] = conj(U[p][q]) = sin_t*cos_p - i*sin_t*sin_p

        double cUpp_r =  cos_t,  cUpp_i = 0.0;
        double cUqq_r =  cos_t,  cUqq_i = 0.0;
        // U^H[p][q] = conj(U[q][p]) where U[q][p] = -sin_t*cos_p + i*sin_t*sin_p
        double cUpq_r = -sin_t * cos_p,  cUpq_i = -sin_t * sin_p;
        // U^H[q][p] = conj(U[p][q]) where U[p][q] = sin_t*cos_p + i*sin_t*sin_p
        double cUqp_r =  sin_t * cos_p,  cUqp_i = -sin_t * sin_p;

        // ---- T = U^H * A (only rows p and q change) -------------------
        double TR[N][N], TI[N][N];
        // Copy all rows
        COPY_T: for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                TR[i][j] = AR[i][j];
                TI[i][j] = AI[i][j];
            }
        }
        // Row p: T[p][j] = U^H[p][p]*A[p][j] + U^H[p][q]*A[q][j]
        UHA_ROW_P: for (int j = 0; j < N; j++) {
            double ar = AR[p][j], ai = AI[p][j];
            double br = AR[q][j], bi = AI[q][j];
            TR[p][j] = cUpp_r*ar - cUpp_i*ai + cUpq_r*br - cUpq_i*bi;
            TI[p][j] = cUpp_r*ai + cUpp_i*ar + cUpq_r*bi + cUpq_i*br;
            local_cycles++;
        }
        // Row q: T[q][j] = U^H[q][p]*A[p][j] + U^H[q][q]*A[q][j]
        UHA_ROW_Q: for (int j = 0; j < N; j++) {
            double ar = AR[p][j], ai = AI[p][j];
            double br = AR[q][j], bi = AI[q][j];
            TR[q][j] = cUqp_r*ar - cUqp_i*ai + cUqq_r*br - cUqq_i*bi;
            TI[q][j] = cUqp_r*ai + cUqp_i*ar + cUqq_r*bi + cUqq_i*br;
            local_cycles++;
        }

        // ---- A = T * U (only columns p and q change) ------------------
        // Copy T -> A
        COPY_A: for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                AR[i][j] = TR[i][j];
                AI[i][j] = TI[i][j];
            }
        }
        // Temporary storage for cols p and q
        double colp_r[N], colp_i[N], colq_r[N], colq_i[N];
        // Col p: A[i][p] = T[i][p]*U[p][p] + T[i][q]*U[q][p]
        TU_COL_P: for (int i = 0; i < N; i++) {
            double tr = TR[i][p], ti = TI[i][p];
            double sr = TR[i][q], si = TI[i][q];
            colp_r[i] = tr*Upp_r - ti*Upp_i + sr*Uqp_r - si*Uqp_i;
            colp_i[i] = tr*Upp_i + ti*Upp_r + sr*Uqp_i + si*Uqp_r;
            local_cycles++;
        }
        // Col q: A[i][q] = T[i][p]*U[p][q] + T[i][q]*U[q][q]
        TU_COL_Q: for (int i = 0; i < N; i++) {
            double tr = TR[i][p], ti = TI[i][p];
            double sr = TR[i][q], si = TI[i][q];
            colq_r[i] = tr*Upq_r - ti*Upq_i + sr*Uqq_r - si*Uqq_i;
            colq_i[i] = tr*Upq_i + ti*Upq_r + sr*Uqq_i + si*Uqq_r;
            local_cycles++;
        }
        // Write back cols
        for (int i = 0; i < N; i++) {
            AR[i][p] = colp_r[i];
            AI[i][p] = colp_i[i];
            AR[i][q] = colq_r[i];
            AI[i][q] = colq_i[i];
        }

        // Enforce Hermitian symmetry and exact zero at (p,q)/(q,p)
        AR[p][q] = 0.0; AI[p][q] = 0.0;
        AR[q][p] = 0.0; AI[q][p] = 0.0;
        // Diagonal should be real for Hermitian
        AI[p][p] = 0.0;
        AI[q][q] = 0.0;

        // ---- V <- V * U (only cols p and q change) --------------------
        double vcolp_r[N], vcolp_i[N], vcolq_r[N], vcolq_i[N];
        V_COL_P: for (int i = 0; i < N; i++) {
            double vr = VR[i][p], vi = VI[i][p];
            double wr = VR[i][q], wi = VI[i][q];
            vcolp_r[i] = vr*Upp_r - vi*Upp_i + wr*Uqp_r - wi*Uqp_i;
            vcolp_i[i] = vr*Upp_i + vi*Upp_r + wr*Uqp_i + wi*Uqp_r;
            local_cycles++;
        }
        V_COL_Q: for (int i = 0; i < N; i++) {
            double vr = VR[i][p], vi = VI[i][p];
            double wr = VR[i][q], wi = VI[i][q];
            vcolq_r[i] = vr*Upq_r - vi*Upq_i + wr*Uqq_r - wi*Uqq_i;
            vcolq_i[i] = vr*Upq_i + vi*Upq_r + wr*Uqq_i + wi*Uqq_r;
            local_cycles++;
        }
        for (int i = 0; i < N; i++) {
            VR[i][p] = vcolp_r[i];
            VI[i][p] = vcolp_i[i];
            VR[i][q] = vcolq_r[i];
            VI[i][q] = vcolq_i[i];
        }

    } // end JACOBI_OUTER

    clock_cycles = local_cycles;

    // ------------------------------------------------------------------
    // Pack outputs
    // ------------------------------------------------------------------
    OUT_EVAL: for (int i = 0; i < N; i++) {
        eigenvalues_re[i] = (eval_t)AR[i][i];
        eigenvalues_im[i] = (eval_t)AI[i][i];
    }
    OUT_EVEC: for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            eigenvectors_re[i][j] = (evec_t)VR[i][j];
            eigenvectors_im[i][j] = (evec_t)VI[i][j];
        }
    }
    ite = (iter_t)last_z;
}
